import {assetTypes,assetClasses,allowedClasses,parseMinor,parseUnits,formatMoney,formatUnits,positionValue} from './portfolio.mjs';
import {LocalStore} from './storage.mjs';
import {ledgerCurrencies,entryNames,couponPeriods,ledgerToday,ledgerId,emptyLedger,validateLedger,normalizeLedger,ledgerView,mutateEntry,removeEntry,setAssetHistory,purgeAsset,removePortfolio,setQuote,defaultTradeCurrency,assetSignature,entryGross,forecastCoupons,nextCouponDate,bondCouponYield,bondYearlyForecast,compositionLedger,signedMinor,roundedRatio} from './ledger.mjs';
import {parseLedgerFile,prepareLedgerImport,LEDGER_MAX_BYTES,decimalMinor,bondFromImport} from './ledger-import.mjs';

const uiApp=document.getElementById('kapital-app'),uiStore=new LocalStore(validateLedger,normalizeLedger),uiAppearance=window.kapitalTheme;
const uiVersion='__APP_VERSION__',uiBuild='__VERSION__';
let uiRegistration=null,uiUpdate={busy:false,status:'',available:''};
const uiEscape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uiMoney=formatMoney,uiUnits=formatUnits,uiSigned=(n,c)=>(n>0?'+':n<0?'−':'')+uiMoney(Math.abs(n),c);
const uiPct=n=>n===null?'—':new Intl.NumberFormat('ru-RU',{maximumFractionDigits:2,minimumFractionDigits:0}).format(n)+'%';
const uiDate=s=>s?s.split('-').reverse().join('.'):'—';
const uiCurrencyMark=c=>({USD:'$',KZT:'тг',RUB:'₽',GBP:'£'}[c]||c);
const uiCurrencyNumber=n=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:2}).format(n/100);
const uiCurrencyRows=rows=>[...rows].sort((a,b)=>['USD','KZT','RUB','GBP'].indexOf(a.currency)-['USD','KZT','RUB','GBP'].indexOf(b.currency));
function uiCurrencyLine(rows,key='value'){return uiCurrencyRows(rows).map(m=>`<span class="currency-amount">${uiCurrencyNumber(m[key])}${uiCurrencyMark(m.currency)}</span>`).join('<span class="currency-divider" aria-hidden="true">/</span>');}
function uiCashBalances(view){return `<div class="cash-balances" aria-label="Наличные по валютам">${uiCurrencyRows(view.currencies.values()).map(m=>`<span class="cash-balance"><span class="cash-currency">${uiCurrencyMark(m.currency)}</span> <strong class="money ${uiTone(m.cash)}">${uiCurrencyNumber(m.cash)}</strong></span>`).join('')}</div>`;}

const uiTone=n=>n>0?'gain':n<0?'loss':'flat';
let uiData=emptyLedger(),uiRevision=0,uiReady=false,uiBusy=false,uiScreen='home',uiPortfolio='',uiAsset='',uiType='stock',uiCurrency='KZT',uiSection='overview',uiHistory=false,uiGroup='type',uiFilter='all',uiEditing='',uiKind='deposit',uiIssuer='',uiMessage='',uiError=false,uiSaved='',uiDefaultCurrency='KZT',uiOffline='Проверяем офлайн-режим…';
let uiImport={method:'file',format:'json',text:'',file:null,target:'new',name:'Импортированный портфель',defaultKind:'deposit',mode:'merge',preview:null,serial:0};
try{uiDefaultCurrency=localStorage.getItem('kapital.defaultCurrency')||'KZT';}catch{}
if(!ledgerCurrencies[uiDefaultCurrency])uiDefaultCurrency='KZT';
const uiChannel=globalThis.BroadcastChannel?new BroadcastChannel('kapital-local-updates'):null;
uiChannel?.addEventListener('message',()=>{if(!uiBusy&&['home','portfolio','assets','cash','graph','composition','history','settings','asset'].includes(uiScreen))uiLoad().then(uiRender).catch(uiFail);else{uiMessage='Записи изменились в другой вкладке. Перед сохранением обновите данные.';uiError=true;}});
function uiThemeStatus(){const t=uiAppearance.getState();return 'Сейчас: '+(t.resolved==='dark'?'ночной':'светлый')+' «Сапфир».'+(t.persistent?'':' Выбор не удалось сохранить: он действует только в этой вкладке.');}
uiAppearance.subscribe(()=>{const status=uiApp.querySelector('#theme-status');if(status)status.textContent=uiThemeStatus();const picker=uiApp.querySelector('#theme-preference');if(picker)picker.value=uiAppearance.getState().preference;});
const uiButton=(label,action,style='secondary',attributes='')=>`<button type="button" class="${style}" data-action="${action}" ${attributes}>${label}</button>`;
const uiSectionTitle=(title,action='')=>`<div class="section"><h2>${title}</h2>${action}</div>`;
const uiEmpty=text=>`<div class="panel empty">${text}</div>`;
const uiField=(name,label,value='',options={})=>`<label for="${name}">${label}</label><input id="${name}" name="${name}" value="${uiEscape(value)}" ${options.type?`type="${options.type}"`:''} ${options.decimal?'inputmode="decimal"':''} ${options.required?'required':''} ${options.maxlength?`maxlength="${options.maxlength}"`:''} ${options.readonly?'readonly':''}>`;
const uiSelect=(name,label,options,value)=>`<label for="${name}">${label}</label><select id="${name}" name="${name}">${options.map(([v,t])=>`<option value="${uiEscape(v)}" ${String(v)===String(value)?'selected':''}>${uiEscape(t)}</option>`).join('')}</select>`;
function uiCurrencyOptions(extra){const available=new Set(['KZT','USD','RUB']);if(extra==='GBP'||uiData.entries.some(e=>e.currency==='GBP'||e.fromCurrency==='GBP'||e.toCurrency==='GBP')||uiData.portfolios.some(p=>p.openingCash.GBP!==undefined))available.add('GBP');return [...available].map(c=>[c,c+' · '+ledgerCurrencies[c].name]);}
const uiPortfolioOptions=()=>uiData.portfolios.map(p=>[p.id,p.name]);
const uiCurrent=()=>uiData.portfolios.find(p=>p.id===uiPortfolio);
const uiCurrentAsset=()=>uiData.assets.find(a=>a.id===uiAsset);
function uiView(){return ledgerView(uiData,uiPortfolio);}
function uiEnsure(){if(!uiCurrent())uiPortfolio=uiData.portfolios[0]?.id||'';if(uiScreen==='asset'&&!uiCurrentAsset())uiScreen='assets';if(uiPortfolio){const v=uiView();if(!v.currencies.has(uiCurrency))uiCurrency=v.currencies.has(uiCurrent().currency)?uiCurrent().currency:[...v.currencies.keys()][0]||'KZT';}}
function uiRoute(){const [screen,id,section]=location.hash.slice(1).split('/');uiScreen=['home','portfolio','assets','asset','asset-edit','entry','cash','graph','composition','history','issuers','issuer-edit','import','settings','new','rename','profit','opening','cash-opening'].includes(screen)?screen:'home';if(['portfolio','cash','graph','assets'].includes(uiScreen)&&id)uiPortfolio=id;if(uiScreen==='portfolio')uiSection=section||'overview';if(uiScreen==='assets'&&['stock','bond','fund'].includes(section))uiType=section;if(uiScreen==='asset'&&id){uiAsset=id;uiPortfolio=uiData.assets.find(a=>a.id===id)?.portfolioId||uiPortfolio;}uiEnsure();}
function uiGo(screen,options={}){Object.entries(options).forEach(([key,value])=>{if(key==='portfolio')uiPortfolio=value;if(key==='asset')uiAsset=value;if(key==='type')uiType=value;if(key==='kind')uiKind=value;if(key==='editing')uiEditing=value;if(key==='issuer')uiIssuer=value;if(key==='section')uiSection=value;});uiScreen=screen;uiEnsure();if(screen==='asset'&&uiCurrentAsset())uiHistory=uiView().positions.get(uiAsset)?.history||false;uiMessage='';uiError=false;const id=screen==='asset'?uiAsset:['portfolio','cash','graph','assets'].includes(screen)?uiPortfolio:'';history.pushState({},'',`#${screen}${id?'/'+id:''}${screen==='portfolio'?'/'+uiSection:screen==='assets'?'/'+uiType:''}`);uiRender();window.scrollTo(0,0);}
window.addEventListener('popstate',()=>{uiRoute();uiMessage='';uiRender();});
function uiRender(){uiEnsure();const active=['new','rename','portfolio','assets','asset','asset-edit','opening'].includes(uiScreen)?'home':['entry','profit'].includes(uiScreen)?'history':uiScreen==='import'?'settings':['cash','graph','issuers','issuer-edit'].includes(uiScreen)?'home':uiScreen;const nav=[['home','◫','Портфели'],['history','⇅','Операции'],['composition','◔','Состав'],['settings','☷','Настройки']];uiApp.innerHTML=`<main class="shell"><header class="header"><div><p class="eyebrow">КАПИТАЛ / ФОКУС</p><h1>${uiScreen==='home'?'Ваши инвестиции':uiScreen==='settings'?'Настройки':uiScreen==='composition'?'Состав портфеля':uiScreen==='history'?'Операции':'Ваш капитал'}</h1></div><button class="iconbutton" type="button" data-action="settings" aria-label="Настройки">☷</button></header>${uiMessage?`<div class="notice ${uiError?'error':''}" role="status">${uiEscape(uiMessage)}</div>`:''}${!uiReady?'<div class="notice error">Хранилище недоступно. Откройте постоянную ссылку в обычной вкладке Firefox. Новые записи отключены.</div>':''}<div id="screen">${uiContent()}</div><p class="save-state">${uiSaved?'Сохранено в браузере · '+new Date(uiSaved).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'}):'Все данные остаются в этом браузере'}</p><p class="save-state">Капитал · Фокус ${uiVersion}</p></main><nav class="nav" aria-label="Разделы приложения"><div class="nav-inner">${nav.map(([id,icon,label])=>`<button type="button" data-action="${id}" aria-current="${active===id?'page':'false'}"><span class="nav-symbol" aria-hidden="true">${icon}</span>${label}</button>`).join('')}</div></nav>`;uiApp.querySelectorAll('button').forEach(b=>b.disabled=uiBusy);if(uiScreen==='entry')uiEntryUpdate();}
function uiPortfolioPicker(){return `<div class="compact-picker">${uiSelect('active-portfolio','Портфель',uiPortfolioOptions(),uiPortfolio)}</div>`;}
function uiCurrencyPicker(view){const values=[...view.currencies.keys()];if(!values.length)values.push('KZT');return `<div class="currency-picker">${uiSelect('view-currency','Валюта итогов',values.map(c=>[c,c]),uiCurrency)}</div>`;}
function uiPortfolioTabs(){return `<div class="portfolio-tabs" role="group" aria-label="Разделы портфеля">${[['overview','Обзор'],['stock','Акции'],['bond','Облигации'],['fund','Фонды'],['cash','Наличные'],['graph','График']].map(([key,label])=>`<button type="button" data-portfolio-section="${key}" aria-pressed="${uiScreen==='portfolio'&&uiSection===key||uiScreen==='assets'&&uiType===key||uiScreen===key}">${label}</button>`).join('')}</div>`;}
function uiStat(label,value,context='',tone=''){return `<div class="panel stat"><span class="small">${label}</span><strong class="money ${tone}">${value}</strong>${context?`<span class="small">${context}</span>`:''}</div>`;}
function uiHome(){const totals=new Map();for(const p of uiData.portfolios){const v=ledgerView(uiData,p.id);for(const m of v.currencies.values())totals.set(m.currency,(totals.get(m.currency)||0)+m.value);}return `${totals.size?`<div class="panel hero-panel"><span class="small">Ваш капитал</span><p class="value currency-line">${uiCurrencyLine([...totals].map(([currency,value])=>({currency,value})))}</p></div>`:''}${uiSectionTitle('Мои портфели',uiButton('+ Новый','new','textbutton'))}${uiData.portfolios.length?uiData.portfolios.map(p=>{const v=ledgerView(uiData,p.id),positions=[...v.positions.values()],counts={stock:0,bond:0,fund:0,history:0};positions.forEach(pos=>pos.history?counts.history++:counts[pos.asset.type]++);return `<div class="home-portfolio swipe-tile" data-swipe-id="${p.id}" data-swipe-kind="portfolio"><button type="button" class="swipe-delete" data-action="remove-portfolio" data-id="${p.id}">Удалить</button><div class="swipe-front"><button class="portfolio" type="button" data-open-portfolio="${p.id}"><span class="row"><span class="badge">${uiEscape(p.name[0].toUpperCase())}</span><span class="grow"><h3>${uiEscape(p.name)}</h3><span class="small">${counts.stock} акц. · ${counts.bond} обл. · ${counts.fund} фонд. · ист. ${counts.history}</span></span><span class="chevron">›</span></span><span class="portfolio-total"><span class="small block">Текущая оценка</span><span class="value currency-line">${uiCurrencyLine(v.currencies.values())}</span></span><span class="portfolio-income"><span class="small block">Реализованный доход${p.snapshotDate?' с '+uiDate(p.snapshotDate):''}</span>${uiCurrencyRows(v.currencies.values()).map(m=>`<span class="income-currency result ${uiTone(m.income)}">${uiSigned(m.income,m.currency)} · ${uiPct(m.returnPercent)}</span>`).join('')}</span></button><div class="tile-tools">${uiButton('✎','rename','icon-edit',`data-id="${p.id}" aria-label="Переименовать ${uiEscape(p.name)}"`)}${uiButton('✕','remove-portfolio','delete-target',`data-id="${p.id}" aria-label="Удалить портфель ${uiEscape(p.name)}"`)}</div></div></div>`;}).join(''):uiEmpty('Создайте портфель. Затем добавьте деньги и инструменты.')}<div class="toolbar">${uiButton('Импорт данных JSON / CSV','import','secondary wide')}</div>`;}
function uiOverview(){const p=uiCurrent(),v=uiView();return `${uiButton('‹ Портфели','home','back')}${uiSectionTitle(uiEscape(p.name),uiButton('✎','rename','textbutton',`data-id="${p.id}" aria-label="Переименовать портфель"`))}${uiPortfolioTabs()}<div class="panel"><p class="small">Текущая оценка портфеля</p><p class="value currency-line">${uiCurrencyLine(v.currencies.values())}</p><hr><h3>Наличные</h3>${uiCashBalances(v)}${uiButton('Движение средств','cash','textbutton')}</div>${uiCurrencyRows(v.currencies.values()).map(m=>`<div class="panel"><p class="small">Результат · ${m.currency}</p>${m.adjustment?`<p class="small">Корректировка исходного отчёта: ${uiSigned(m.adjustment,m.currency)}</p>`:''}<p class="result ${uiTone(m.profit)}">Изменение стоимости: ${uiSigned(m.profit,m.currency)}</p><hr><p class="small">Реализованный доход ${p.snapshotDate?'с '+uiDate(p.snapshotDate):'за всё время'}</p><p class="result ${uiTone(m.income)}">${uiSigned(m.income,m.currency)} · ${uiPct(m.returnPercent)}</p><p class="hint">Процент: реализованный доход / максимальный вложенный капитал. Текущая оценка также учитывает открытые позиции.</p></div>`).join('')}${p.legacyReportValue?`<div class="notice">Исходная оценка снимка: ${uiMoney(p.legacyReportValue.valueMinor,p.legacyReportValue.currency)}. Наличные из исходной валютной разбивки разделены; оценки бумаг сохранены в валюте прежнего снимка. Валюты не суммируются.</div>`:''}${p.snapshotDate?`<p class="hint">Начальные остатки на ${uiDate(p.snapshotDate)}. Исторические покупки и доход до этой даты не восстанавливались.</p>`:''}${v.warnings.map(w=>`<div class="notice error">${uiEscape(w.message)}</div>`).join('')}<div class="two main-actions">${uiButton('+ Пополнение','entry','secondary','data-kind="deposit"')}${uiButton('+ Купить актив','entry','primary','data-kind="buy"')}</div>${uiSectionTitle('Состав портфеля')}${uiCurrencyPicker(v)}${uiChartComposition(v)}${uiSectionTitle('Ближайшие выплаты')}${uiForecastRows(ledgerToday(),uiMonthEnd())}`;}
function uiMonthStart(){return ledgerToday().slice(0,7)+'-01';}
function uiMonthEnd(){const [y,m]=ledgerToday().split('-').map(Number);return `${y}-${String(m).padStart(2,'0')}-${new Date(Date.UTC(y,m,0)).getUTCDate()}`;}
function uiForecastRows(start,end){const coupons=forecastCoupons(uiData,uiPortfolio,start,end),v=uiView();const redemptions=uiData.assets.filter(a=>a.portfolioId===uiPortfolio&&a.type==='bond'&&a.bond.maturityDate&&a.bond.maturityDate>=start&&a.bond.maturityDate<=end&&[...v.positions.get(a.id).pools.values()].some(p=>p.quantityUnits>0));return `${coupons.length||redemptions.length?'<div class="panel">'+coupons.map(c=>`<div class="settings-row"><span class="grow"><strong>${uiEscape(c.ticker)}</strong><span class="small block">Ожидаемый купон · ${uiDate(c.date)}</span></span><span class="money">${uiMoney(c.amountMinor,c.currency)}</span>${uiButton('Подтвердить','confirm-coupon','textbutton',`data-id="${c.assetId}" data-date="${c.date}" data-amount="${c.amountMinor}"`)}</div>`).join('')+redemptions.map(a=>`<div class="settings-row"><span class="grow"><strong>${uiEscape(a.ticker)}</strong><span class="small block">Ожидаемое погашение · ${uiDate(a.bond.maturityDate)}</span></span>${uiButton('Подтвердить','entry','textbutton',`data-kind="redemption" data-asset="${a.id}"`)}</div>`).join('')+'</div>':uiEmpty('На выбранный период ожидаемых выплат нет.')}<p class="hint">Прогноз не входит в наличные и доход. Подтвердите фактическую выплату после поступления денег.</p>`;}
function uiAssetRows(view,list){return list.map(pos=>{const a=pos.asset,pools=[...pos.pools.values()],summary=pools.map(pool=>`<div class="portfolio-bottom"><span><span class="asset-value value">${uiMoney(pool.marketValue,pool.currency)}</span><span class="small block">Остаток: ${uiUnits(pool.quantityUnits)} шт.</span><span class="small block">${pool.basis==='snapshot'?'База снимка':'Вложено'}: ${pool.quantityUnits>0?uiMoney(pool.costMinor,pool.currency):'—'}</span></span><span class="result ${uiTone(pool.realized)}">${uiSigned(pool.realized,pool.currency)}</span></div>`).join('');return `<div class="swipe-tile" data-swipe-id="${a.id}"><button type="button" class="swipe-delete" data-action="remove-asset" data-id="${a.id}">Удалить</button><div class="swipe-front"><button class="portfolio asset-tile" type="button" data-open-asset="${a.id}"><span class="row"><span class="asset-mark" style="background:${assetTypes[a.type].color}"></span><span class="grow"><h3>${uiEscape(a.ticker||a.name)} ${a.comment?`<span class="asset-comment">${uiEscape(a.comment)}</span>`:''}</h3><span class="small">${uiEscape(a.name)} · ${assetClasses[a.assetClass].name}</span></span><span class="chevron">›</span></span>${summary||'<p class="small block">Операций пока нет</p>'}${pos.history?`<p class="hint history-reason">${uiEscape(pos.reason)}</p><p class="small">${pools.map(pool=>`${pool.basis==='snapshot'?'С даты снимка:':'Период владения:'} ${uiDate(pool.firstDate)} — ${uiDate(pool.quantityUnits>0?ledgerToday():pool.lastDate)} · ${pool.basis==='snapshot'?'Начальная база и покупки':'Куплено'}: ${uiMoney(pool.totalBoughtMinor,pool.currency)} · Выручка: ${uiMoney(pool.proceeds,pool.currency)} · Выплаты: ${uiMoney(pool.income,pool.currency)}`).join('<br>')}</p>`:''}${a.type==='bond'?`<p class="hint">Купон: ${uiDate(nextCouponDate(a.bond,ledgerToday()))} · Погашение: ${uiDate(a.bond.maturityDate)}</p><p class="small">В этом месяце ожидается: ${uiMoney(forecastCoupons(uiData,uiPortfolio,uiMonthStart(),uiMonthEnd()).filter(c=>c.assetId===a.id).reduce((sum,c)=>sum+c.amountMinor,0),a.bond.currency)}</p>`:''}</button>${uiButton('✕','remove-asset','delete-target',`data-id="${a.id}" aria-label="Удалить плитку ${uiEscape(a.ticker||a.name)}"`)}${pos.history?uiButton('Вернуть в активные','restore-asset','textbutton restore-tile',`data-id="${a.id}"`):''}</div></div>`;}).join('')||uiEmpty(uiHistory?'Закрытых или скрытых инструментов пока нет.':'Инструментов пока нет. Добавьте тикер и запишите покупку.');}
function uiAssets(){const v=uiView(),all=[...v.positions.values()].filter(pos=>pos.asset.type===uiType),active=all.filter(p=>!p.history),archived=all.filter(p=>p.history),list=uiHistory?archived:active;const poolRows=(uiHistory?list:all).flatMap(pos=>[...pos.pools.values()]),m=poolRows.filter(p=>p.currency===uiCurrency),forecast=forecastCoupons(uiData,uiPortfolio,uiMonthStart(),uiMonthEnd()).filter(c=>c.currency===uiCurrency);const invested=m.reduce((s,p)=>s+p.costMinor,0),realized=m.reduce((s,p)=>s+p.realized,0),fees=uiData.entries.filter(e=>e.portfolioId===uiPortfolio&&all.some(p=>p.asset.id===e.assetId)&&(e.feeCurrency||e.currency)===uiCurrency).reduce((s,e)=>s+(e.feeMinor||0),0);return `${uiButton('‹ Портфель','portfolio','back')}${uiSectionTitle(assetTypes[uiType].name,uiButton('+ Тикер','asset-new','textbutton'))}${uiPortfolioTabs()}${uiCurrencyPicker(v)}<div class="summary-strip">${uiStat('Вложено',uiMoney(invested,uiCurrency))}${uiType==='bond'?uiStat('Купоны в месяце',uiMoney(forecast.reduce((s,c)=>s+c.amountMinor,0),uiCurrency),'Ожидаемые'):uiStat('Закрытый результат',uiMoney(realized,uiCurrency),'',uiTone(realized))}${uiType==='bond'?uiStat('Выплачено купонов',uiMoney(poolRows.filter(p=>p.currency===uiCurrency).reduce((s,p)=>s+p.income,0),uiCurrency)):uiStat('Комиссии',uiMoney(fees,uiCurrency))}</div>${uiType==='bond'?uiButton('База данных эмитентов','issuers','secondary wide')+uiButton('Задать номинал для бумаг без номинала','bulk-nominal','textbutton'):''}<div class="segments history-switch"><button type="button" data-asset-tab="active" aria-pressed="${!uiHistory}">Активные (${active.length})</button><button type="button" data-asset-tab="history" aria-pressed="${uiHistory}">История (${archived.length})</button></div>${uiHistory?`<p class="hint">Бумаг: ${list.length}. Результат: ${uiMoney(realized,uiCurrency)}. Выплаты: ${uiMoney(m.reduce((s,p)=>s+p.income,0),uiCurrency)}. Перенос в историю не меняет деньги и операции.</p>`:''}${uiAssetRows(v,list)}${uiSectionTitle('Журнал движения активов')}${uiJournal(all.map(p=>p.asset.id))}`;}
function uiEntryRows(entries,view){return entries.map(e=>{const result=view.entryResults.get(e.id),a=uiData.assets.find(a=>a.id===e.assetId);const cash=result?Object.entries(result.cashChanges).map(([c,n])=>uiSigned(n,c)).join(' · '):'';return `<div class="operation ledger-operation" ${a?`data-open-row-asset="${a.id}"`: ""}><div class="grow">${a?`<button type="button" class="journal-open" data-open-asset="${a.id}">${entryNames[e.kind]} · ${uiEscape(a.ticker||a.name)}</button>`:`<h3>${entryNames[e.kind]}</h3>`}<span class="small">${uiDate(e.date)}${e.externalId?' · Импорт':''}</span><span class="small money">${cash||'—'}</span>${e.quantityUnits?`<span class="small">${uiUnits(e.quantityUnits)} шт. × ${uiMoney(e.priceMinor,e.currency)}</span>`:''}${e.note?`<span class="small">${uiEscape(e.note)}</span>`:''}${e.reportedProfitMinor!==undefined?`<span class="small">Результат брокера справочно: ${uiMoney(e.reportedProfitMinor,e.currency)}</span>`:''}${e.kind==='sell'?uiButton(`Прибыль / убыток: ${result?.profitMinor===null?'не определён':uiSigned(result?.profitMinor||0,e.currency)}${e.profitOverrideMinor!==undefined?' · вручную':''}`,'profit','textbutton',`data-id="${e.id}"`):e.kind==='redemption'?`<span class="small">Результат: ${result?.profitMinor===null?'—':uiMoney(result?.profitMinor||0,e.currency)}</span>`:''}</div><div class="operation-tools">${uiButton('Изменить','edit-entry','textbutton',`data-id="${e.id}"`)}${uiButton('Удалить','remove-entry','textbutton danger',`data-id="${e.id}"`)}</div></div>`;}).join('')||'<p class="empty">Записей пока нет.</p>';}
function uiJournal(assetIds=null){const view=uiView(),entries=view.entries.filter(e=>(!assetIds||assetIds.includes(e.assetId))&&(uiFilter==='all'||e.kind===uiFilter)).slice().reverse();const options=[['all','Все'],...Object.entries(entryNames).filter(([k])=>!assetIds||['buy','sell','redemption','dividend','coupon'].includes(k))];return `${uiSelect('journal-filter','Тип операций',options,uiFilter)}<div class="panel operation-list">${uiEntryRows(entries,view)}</div>`;}
function uiBondYears(asset){const rows=bondYearlyForecast(uiData,asset);if(!rows.length)return '';return `${uiSectionTitle('Купоны по годам владения')}<div class="panel"><div class="data-table"><table><thead><tr><th>Год</th><th>К получению</th><th>Подтверждено</th><th>% год.</th></tr></thead><tbody>${rows.map(row=>`<tr><td>${row.year}</td><td>${uiMoney(row.pendingMinor,row.currency)}</td><td>${uiMoney(row.confirmedMinor,row.currency)}</td><td>${uiPct(row.annualPercent)}</td></tr>`).join('')}</tbody></table></div><p class="hint">Прогноз купонной доходности учитывает стоимость и календарное время владения в каждом году. Это не доходность к погашению; прогноз не входит в наличные.</p></div>`;}
function uiAssetPage(){const a=uiCurrentAsset(),v=uiView(),pos=v.positions.get(a.id),pools=[...pos.pools.values()];return `${uiButton('‹ Инструменты','asset-list','back')}${uiSectionTitle(uiEscape(a.ticker||a.name),uiButton('Изменить','asset-edit','textbutton'))}<p class="hint">${uiEscape(a.name)}${a.comment?' · '+uiEscape(a.comment):''}</p>${pos.history?`<div class="notice">Бумага в истории: ${uiEscape(pos.reason)}. ${uiButton('Вернуть в активные','restore-asset','textbutton',`data-id="${a.id}"`)}</div>`:''}${pos.warnings.map(w=>`<div class="notice error">${uiEscape(w.message)}</div>`).join('')}${pools.map(pool=>`<div class="panel"><span class="small">${pool.currency} · Остаток ${uiUnits(pool.quantityUnits)} шт.</span><p class="value hero-value">${uiMoney(pool.marketValue,pool.currency)}</p><div class="two"><div><p class="small">${pool.basis==='snapshot'?'Средняя база снимка':'Средневзв. цена владения'}</p><p class="money">${pool.quantityUnits>0?uiMoney(pool.averagePriceMinor,pool.currency):'—'}</p></div><div><p class="small">${pool.basis==='snapshot'?'База оставшихся бумаг':'Вложено сейчас'}</p><p class="money">${pool.quantityUnits>0?uiMoney(pool.costMinor,pool.currency):'—'}</p></div></div><hr><p class="small">${pool.basis==='snapshot'?'Начальная оценка + последующие покупки':'Куплено всего'}: ${uiMoney(pool.totalBoughtMinor,pool.currency)}</p><p class="small">Выручка: ${uiMoney(pool.proceeds,pool.currency)} · Комиссии: ${uiMoney(pool.fees,pool.currency)}</p><p class="result ${uiTone(pool.realized)}">Закрытый результат: ${uiSigned(pool.realized,pool.currency)}</p>${pool.basis==='snapshot'?'<p class="hint">Себестоимость до снимка неизвестна. Результат считается относительно оценки на дату снимка.</p>':''}${a.type==='bond'?`<p class="hint">Купонная доходность, % год.: ${uiPct(bondCouponYield(pool,a.bond))}. Это не доходность к погашению.</p><p class="small">Купоны к получению за месяц: ${uiMoney(forecastCoupons(uiData,uiPortfolio,uiMonthStart(),uiMonthEnd()).filter(c=>c.assetId===a.id&&c.currency===pool.currency).reduce((s,c)=>s+c.amountMinor,0),pool.currency)}</p>`:''}<div class="toolbar">${uiButton('Обновить текущую цену','quote','textbutton',`data-currency="${pool.currency}"`)}</div></div>`).join('')}${a.type==='bond'?`<div class="panel"><h3>Параметры облигации</h3><p class="hint">Номинал: ${a.bond.nominalMinor?uiMoney(a.bond.nominalMinor,a.bond.currency):'не указан'} · ${couponPeriods[a.bond.periodMonths]}</p><p class="small">Купон за 1 шт.: ${uiMoney(a.bond.couponMinor,a.bond.currency)} · Дата: ${uiDate(nextCouponDate(a.bond,ledgerToday()))} · Погашение: ${uiDate(a.bond.maturityDate)}</p>${!a.bond.nominalMinor?'<p class="hint loss">Номинал не указан. Для подтверждения погашения введите фактическую сумму. Предложение по средней цене не включает комиссию покупки.</p>':''}</div>`:''}<div class="action-grid">${[['buy','Купить'],['sell','Продать'],[a.type==='bond'?'coupon':'dividend',a.type==='bond'?'Купон':'Дивиденды'],...(a.type==='bond'?[['redemption','Погашение']]:[])].map(([kind,label])=>uiButton(label,'entry',kind==='buy'?'primary':'secondary',`data-kind="${kind}" data-asset="${a.id}"`)).join('')}</div><div class="toolbar">${uiButton('Начальные остатки','opening','textbutton')}${uiButton('Перенести в историю','archive-asset','textbutton',`data-id="${a.id}"`)}${uiButton('Удалить плитку','remove-asset','textbutton danger',`data-id="${a.id}"`)}</div>${a.type==='bond'?uiBondYears(a):''}${['buy','sell',...(a.type==='bond'?['redemption','coupon']:['dividend'])].map(kind=>uiSectionTitle(kind==='redemption'?'История погашений':kind==='buy'?'История покупок':kind==='sell'?'История продаж':kind==='coupon'?'История купонов':'История дивидендов')+`<div class="panel operation-list">${uiEntryRows(v.entries.filter(e=>e.assetId===a.id&&e.kind===kind).slice().reverse(),v)}</div>`).join('')}`;}
function uiCash(){const v=uiView();return `${uiButton('‹ Портфель','portfolio','back')}${uiSectionTitle('Наличные')}${uiCurrent().unallocatedOpening?'<div class="notice">Остаток из прежней версии является нераспределённой оценкой, а не подтверждёнными деньгами. Уточните начальные денежные остатки перед расходной операцией.</div>':''}${uiPortfolioTabs()}<div class="panel">${uiCashBalances(v)}</div><div class="action-grid">${[['deposit','Пополнение'],['withdrawal','Вывод средств'],['fx','Конвертация'],['fee','Комиссия / сбор']].map(([k,t])=>uiButton(t,'entry',k==='deposit'?'primary':'secondary',`data-kind="${k}"`)).join('')}</div><p class="hint">Учитываются только подтверждённые операции. Каждая валюта ведётся отдельно. Конвертация записывает обе стороны обмена.</p>${uiButton('Изменить начальные денежные остатки','cash-opening','textbutton')}${uiSectionTitle('История движения средств')}${uiJournal()}`;}
function uiChartComposition(v){const parts=compositionLedger(v,uiCurrency,uiGroup);let at=0;const sum=parts.reduce((s,p)=>s+p.value,0),gradient=parts.map(p=>{const start=at;at+=p.value/sum*100;return `${p.color} ${start}% ${at}%`;}).join(',');return `<div class="panel"><div class="segments"><button type="button" data-chart-group="type" aria-pressed="${uiGroup==='type'}">По типам</button><button type="button" data-chart-group="class" aria-pressed="${uiGroup==='class'}">По классам</button></div>${parts.length?`<div class="donut" role="img" aria-label="${uiEscape(parts.map(p=>p.name+': '+p.percentTenths/10+'%').join(', '))}" style="background:conic-gradient(${gradient})"><div class="donut-hole"><strong>100%</strong><span class="small">${uiCurrency}</span></div></div><div class="chart-legend">${parts.map(p=>`<div class="legend-row"><span class="swatch" style="background:${p.color}"></span><span class="grow">${p.name}<span class="small">${uiMoney(p.value,uiCurrency)}</span></span><strong>${uiPct(p.percentTenths/10)}</strong></div>`).join('')}</div>`:'<p class="empty">Нет положительной стоимости для диаграммы.</p>'}${v.currencies.get(uiCurrency)?.adjustment?`<p class="hint">Корректировка отчёта: ${uiSigned(v.currencies.get(uiCurrency).adjustment,uiCurrency)}</p>`:""}${(v.currencies.get(uiCurrency)?.cash||0)<0?`<p class="hint loss">Денежный остаток: ${uiMoney(v.currencies.get(uiCurrency).cash,uiCurrency)}</p>`:""}<p class="hint">Доли внутри одной валюты; свободные средства включены. Отрицательные денежные остатки и корректировки отчёта показаны отдельно и не являются сектором диаграммы.</p></div>`;}
function uiGraph(){const v=uiView(),m=v.currencies.get(uiCurrency)||{history:[],capital:0,income:0},points=m.history.slice();if(points.length&&points.at(-1).date<ledgerToday())points.push({...points.at(-1),date:ledgerToday()});const width=Math.max(240,Math.min(400,window.innerWidth-80)),height=228,left=60,right=12,top=20,bottom=45,values=points.map(p=>p.value),min=Math.min(0,...values),max=Math.max(1,...values),range=max-min||1;const start=points[0]?.date||ledgerToday(),end=points.at(-1)?.date||start,dateN=s=>Date.parse(s+'T12:00:00Z'),span=dateN(end)-dateN(start)||1,x=s=>left+(dateN(s)-dateN(start))/span*(width-left-right),y=n=>height-bottom-(n-min)/range*(height-top-bottom);let path='';points.forEach((p,i)=>{if(i===0)path=`M ${x(p.date)} ${y(p.value)}`;else path+=` H ${x(p.date)} V ${y(p.value)}`;});return `${uiButton('‹ Портфель','portfolio','back')}${uiSectionTitle('График портфеля')}${uiPortfolioTabs()}${uiCurrencyPicker(v)}<div class="panel"><h3>Капитал + реализованный доход</h3><p class="value hero-value">${uiMoney(m.capital+m.income,uiCurrency)}</p><p class="hint">Капитал: ${uiMoney(m.capital,uiCurrency)} · Доход: ${uiMoney(m.income,uiCurrency)}</p>${points.length?`<svg class="portfolio-graph" viewBox="0 0 ${width} ${height}" role="img" aria-label="График капитала и реализованного дохода в ${uiCurrency}"><title>Капитал и реализованный доход, ${uiCurrency}</title>${[0,.5,1].map(f=>{const n=min+range*f;return `<line x1="${left}" x2="${width-right}" y1="${y(n)}" y2="${y(n)}" stroke="var(--line)"/><text x="${left-6}" y="${y(n)+4}" text-anchor="end" fill="var(--muted)">${new Intl.NumberFormat('ru-RU',{notation:'compact',maximumFractionDigits:1}).format(n/100)}</text>`;}).join('')}<path d="${path}" fill="none" stroke="var(--link)" stroke-width="2"/><circle cx="${x(points.at(-1).date)}" cy="${y(points.at(-1).value)}" r="3" fill="var(--link)"><title>${uiDate(points.at(-1).date)}: ${uiMoney(points.at(-1).value,uiCurrency)}</title></circle><text x="${left}" y="${height-15}" fill="var(--muted)">${uiDate(start)}</text><text x="${width-right}" y="${height-15}" text-anchor="end" fill="var(--muted)">${uiDate(end)}</text></svg>`:uiEmpty('График появится после первых операций.')}<p class="hint">Подтверждённые дивиденды за вычетом налога, купоны, результаты продаж и погашений, комиссии. Рыночная переоценка открытых позиций показана отдельно в обзоре.</p></div>${uiSectionTitle('Дневные итоги')}<div class="panel"><div class="data-table"><table><thead><tr><th>Дата</th><th>Капитал</th><th>Доход</th></tr></thead><tbody>${points.slice(-120).map(p=>`<tr><td>${uiDate(p.date)}</td><td>${uiMoney(p.capital,uiCurrency)}</td><td>${uiMoney(p.income,uiCurrency)}</td></tr>`).join('')}</tbody></table></div>${points.length>120?'<p class="hint">Последние 120 дат. Все операции сохранены в журнале и JSON.</p>':''}</div>`;}

function uiBondFields(bond={currency:'KZT',couponMinor:0,nominalMinor:0,couponRate:0,periodMonths:12,anchorDate:'',maturityDate:''}){return `<div class="bond-fields">${uiField('nominal','Номинал за 1 бумагу',bond.nominalMinor/100,{decimal:true})}${uiField('coupon-amount','Купон за 1 бумагу за период',bond.couponMinor/100,{decimal:true})}${uiSelect('coupon-frequency','Период выплаты купонов',Object.entries(couponPeriods),bond.periodMonths)}${uiField('coupon-date','Базовая дата выплаты купона',bond.anchorDate,{type:'date'})}${uiField('maturity-date','Дата погашения',bond.maturityDate,{type:'date'})}${uiField('coupon-rate','Купонная ставка, % год.',bond.couponRate,{decimal:true})}<p class="hint">Сохраняется исходный день месяца: 31 января → последний день февраля → 31 марта. Поступления денег подтверждаются отдельными операциями.</p></div>`;}
function uiAssetForm(){const a=uiCurrentAsset(),editing=Boolean(a),type=a?.type||uiType,bond=a?.bond;return `${uiButton('‹ Инструменты','asset-list','back')}<h2>${editing?'Параметры инструмента':'Добавить тикер'}</h2><form class="form" data-ledger-form="asset"><div id="issuer-picker" ${type!=='bond'?'hidden':''}>${uiSelect('issuer-choice','Данные из базы эмитентов',[['','Заполнить вручную'],...uiData.issuers.map(i=>[i.id,i.ticker+' · '+i.name])],'')}</div>${uiField('asset-ticker','Тикер / ISIN',a?.ticker||'',{required:true,maxlength:40})}${uiField('asset-name','Название',a?.name||'',{required:true,maxlength:100})}${uiSelect('asset-type','Тип актива',Object.entries(assetTypes).map(([k,v])=>[k,v.name]),type)}${uiSelect('asset-class','Класс актива',allowedClasses(type).map(k=>[k,assetClasses[k].name]),a?.assetClass||allowedClasses(type)[0])}${uiSelect('asset-currency','Валюта по умолчанию',uiCurrencyOptions(a?.currency),a?.currency||'KZT')}${uiField('asset-comment','Комментарий рядом с тикером',a?.comment||'',{maxlength:500})}<div id="bond-editor" ${type!=='bond'?'hidden':''}>${uiBondFields(bond)}</div><div class="form-actions"><button class="primary" type="submit">Сохранить инструмент</button>${uiButton('Отмена','asset-list')}</div></form>`;}
function uiIssuers(){return `${uiButton('‹ Облигации','bonds','back')}${uiSectionTitle('База данных эмитентов',uiButton('+ Добавить','issuer-new','textbutton'))}${uiData.issuers.map(i=>`<div class="swipe-tile" data-swipe-id="${i.id}" data-swipe-kind="issuer"><button type="button" class="swipe-delete" data-action="remove-issuer" data-id="${i.id}">Удалить</button><div class="swipe-front issuer-tile panel"><button type="button" class="issuer-open" data-edit-issuer="${i.id}"><h3>${uiEscape(i.ticker)}</h3><p class="small">${uiEscape(i.name)}</p><p class="hint">${i.bond.currency} · ${couponPeriods[i.bond.periodMonths]}<br>Купон: ${uiDate(i.bond.anchorDate)} · Погашение: ${uiDate(i.bond.maturityDate)}</p></button>${uiButton('✕','remove-issuer','delete-target',`data-id="${i.id}" aria-label="Удалить эмитента ${uiEscape(i.ticker)}"`)}</div></div>`).join('')||uiEmpty('Добавьте эмитента, чтобы автоматически заполнять параметры облигаций при создании тикера.')}<p class="hint">Удаление из справочника не изменяет инструменты, операции и выплаты в портфелях.</p>`;}
function uiIssuerForm(){const i=uiData.issuers.find(i=>i.id===uiIssuer);return `${uiButton('‹ Эмитенты','issuers','back')}<h2>${i?'Изменить эмитента':'Новый эмитент'}</h2><form class="form" data-ledger-form="issuer">${uiField('issuer-ticker','Тикер',i?.ticker||'',{required:true,maxlength:40})}${uiField('issuer-name','Название',i?.name||'',{required:true,maxlength:100})}${uiSelect('issuer-currency','Валюта облигации',uiCurrencyOptions(i?.bond.currency),i?.bond.currency||'KZT')}${uiBondFields(i?.bond)}<div class="form-actions"><button class="primary" type="submit">Сохранить эмитента</button>${uiButton('Отмена','issuers')}</div></form>`;}
function uiEntryForm(){const edit=uiData.entries.find(e=>e.id===uiEditing),kind=edit?.kind||uiKind,isAsset=['buy','sell','dividend','coupon','redemption'].includes(kind),assets=uiData.assets.filter(a=>a.portfolioId===uiPortfolio&&(!['coupon','redemption'].includes(kind)||a.type==='bond')&&(kind!=='dividend'||a.type!=='bond')),a=assets.find(a=>a.id===(edit?.assetId||uiAsset))||assets[0],currency=edit?.currency||((kind==='coupon'&&a?.bond)?a.bond.currency:(isAsset&&a)?defaultTradeCurrency(uiData,a):'KZT');if(isAsset&&!assets.length)return `${uiButton('‹ Портфель','portfolio','back')}${uiEmpty('Сначала добавьте тикер инструмента.')}${uiButton('+ Добавить тикер','asset-new','primary wide')}`;const view=uiView(),pool=a?view.positions.get(a.id)?.pools.get(currency):null;let price=edit?.priceMinor??(kind==='redemption'?(a?.bond?.nominalMinor||(pool&&pool.quantityUnits>0?roundedRatio(BigInt(pool.costMinor-pool.buyFeesMinor)*1000000n,BigInt(pool.quantityUnits)):0)):(a?.quotes[currency]?.priceMinor||0));let qty=edit?.quantityUnits??(['sell','redemption'].includes(kind)?Math.max(0,pool?.quantityUnits||0):1000000);const amount=edit?.amountMinor??(kind==='coupon'&&a?.bond?positionValue(Math.max(0,pool?.quantityUnits||0),a.bond.couponMinor):0),tax=edit?.taxMinor||0;return `${uiButton('‹ Назад',a?'asset':'portfolio','back')}<h2>${edit?'Изменить: ':''}${kind==='buy'?'Приобретение актива':entryNames[kind]}</h2><form class="form" data-ledger-form="entry" data-kind="${kind}" data-last-currency="${currency}" data-fee-explicit="${edit?.feeCurrency?'yes':''}">${uiSelect('entry-portfolio','Портфель',uiPortfolioOptions(),uiPortfolio)}${isAsset?uiSelect('entry-asset','Инструмент',assets.map(a=>[a.id,a.ticker+' · '+assetTypes[a.type].single]),a?.id):''}${isAsset?uiButton('+ Добавить новый тикер','asset-new','textbutton'):''}${isAsset&&a?.type==='bond'?uiField('entry-nominal','Номинал за 1 бумагу, '+a.bond.currency,a.bond.nominalMinor/100,{decimal:true,readonly:true}):''}${uiField('entry-date','Дата операции',edit?.date||ledgerToday(),{type:'date',required:true})}${kind==='fx'?`${uiSelect('from-currency','Отдаю',uiCurrencyOptions(edit?.fromCurrency),edit?.fromCurrency||'KZT')}${uiField('from-amount','Сумма отдачи',edit?edit.fromMinor/100:'',{decimal:true,required:true})}${uiSelect('to-currency','Получаю',uiCurrencyOptions(edit?.toCurrency),edit?.toCurrency||'USD')}${uiField('to-amount','Сумма получения',edit?edit.toMinor/100:'',{decimal:true,required:true})}${uiField('exchange-rate','Курс: единиц получаемой валюты за 1 отдаваемую',edit?edit.toMinor/edit.fromMinor:'',{decimal:true})}<p class="hint">Введите обе суммы для расчёта курса либо сумму и курс для расчёта второй стороны. Загрузка курсов из интернета не выполняется.</p>`:`${uiSelect('entry-currency','Валюта операции',uiCurrencyOptions(currency),currency)}${['buy','sell','redemption'].includes(kind)?`${uiField('entry-quantity','Количество бумаг / паёв',qty?qty/1000000:'',{decimal:true,required:true})}${uiField('entry-price','Цена за 1 бумагу в деньгах',price/100,{decimal:true,required:true})}<p class="hint">Для облигаций вводите денежную стоимость одной бумаги, а не процент от номинала.</p>${uiField('entry-fee','Комиссия за операцию',(edit?.feeMinor||0)/100,{decimal:true})}${uiSelect('fee-currency','Валюта комиссии',uiCurrencyOptions(edit?.feeCurrency||currency),edit?.feeCurrency||currency)}`:`${uiField('entry-amount',['dividend','coupon'].includes(kind)?'Начислено до налога':'Сумма',amount?amount/100:'',{decimal:true,required:true})}${['dividend','coupon'].includes(kind)?`<div class="two">${uiField('tax-amount','Сумма налога',tax/100,{decimal:true})}${uiField('tax-rate','Ставка налога, %',edit?.taxRate??(amount?Number((tax/amount*100).toFixed(6)):0),{decimal:true})}</div>${kind==='coupon'?uiField('scheduled-date','Дата выплаты по графику (если известна)',edit?.scheduledDate||nextCouponDate(a?.bond,edit?.date||ledgerToday()),{type:'date'}):''}`:''}`}`}${uiField('entry-note','Примечание',edit?.note||'',{maxlength:500})}<div id="entry-preview" class="notice" aria-live="polite"></div><p class="hint">Деньги учитываются по факту. Погашения и купоны из прогноза автоматически не начисляются.</p><div class="form-actions"><button class="primary" type="submit">${edit?'Сохранить изменения':'Записать операцию'}</button>${uiButton('Отмена','portfolio')}</div></form>`;}
function uiImportScreen(){const state=uiImport,p=state.preview;return `${uiButton('‹ Портфели','home','back')}<h2>Импорт JSON / CSV</h2><p class="hint">Данные добавляются в выбранный портфель. Повторные записи пропускаются; полное восстановление выбирается отдельно.</p><form class="form" data-ledger-form="import-preview">${uiSelect('import-target','Куда добавить',[['new','Новый портфель'],...uiPortfolioOptions()],state.target)}${uiField('import-name','Название нового портфеля',state.name,{maxlength:60})}${uiSelect('import-format','Формат',[['json','JSON'],['csv','CSV']],state.format)}${uiSelect('import-method','Источник',[['file','Файл с телефона'],['text','Вставить текст']],state.method)}${state.method==='file'?'<label for="import-file">Файл, до 12 МБ</label><input id="import-file" type="file" accept=".json,.csv,application/json,text/csv,text/plain">':`<label for="import-text">Данные</label><textarea id="import-text" rows="8" spellcheck="false" autocomplete="off" autocapitalize="off">${uiEscape(state.text)}</textarea>`}${state.file?`<p class="hint">Выбран: ${uiEscape(state.file.name)}</p>`:''}${state.format==='csv'?uiSelect('import-default-kind','Тип строк без столбца type',[['deposit','Пополнения'],['withdrawal','Выводы'],['buy','Покупки акций / фондов'],['sell','Продажи акций / фондов'],['bondBuy','Покупки облигаций'],['bondSell','Продажи облигаций'],['dividend','Дивиденды'],['coupon','Купоны'],['redemption','Погашения'],['fx','Конвертации'],['fee','Комиссии']],state.defaultKind):''}${uiSelect('import-mode','Способ загрузки',[['merge','Добавить в выбранный портфель'],['restore','Заменить все записи из полной резервной копии']],state.mode)}<div class="form-actions"><button type="submit" class="primary">Проверить данные</button></div></form>${p?`<div class="panel import-review"><h2>Предпросмотр импорта</h2><p class="hint">Операций к добавлению: ${p.added}. Дублей пропущено: ${p.skipped}. Портфелей после импорта: ${p.data.portfolios.length}.</p>${p.warnings.length?`<div class="notice error">${p.warnings.map(uiEscape).join('<br>')}</div>`:'<p class="hint">Ошибок остатков не обнаружено.</p>'}${uiButton(p.restoring?'Заменить все записи':'Подтвердить добавление','import-apply','primary wide')}</div>`:''}<div class="panel"><h3>Поддерживаемые столбцы CSV</h3><p class="hint">type, date, ticker, assetType, currency, amount, quantity, price, commission, feeCurrency, taxAmount, taxRate, fromCurrency, fromAmount, toCurrency, toAmount, rate, nominal, couponAmount, couponDate, couponFrequency, maturityDate, external_id, note.</p><p class="hint">Разделитель — запятая или точка с запятой; даты — ГГГГ-ММ-ДД или ДД.ММ.ГГГГ. Поддерживаются русские названия: тип, дата, тикер, валюта, сумма, количество, цена, комиссия, налог, номинал.</p>${uiButton('Скачать пример CSV','csv-example','textbutton')}<hr>${uiButton('Экспорт текущих данных','export','textbutton')}${uiButton('Копия до прошлого импорта','export-before-import','textbutton')}</div>`;}
function uiUpdatePanel(){const status=uiUpdate.status||(uiUpdate.available?`Доступна версия ${uiUpdate.available}.`:'');return `${uiSectionTitle('Приложение')}<div class="panel"><p class="small">Текущая версия</p><p class="value" id="app-version">${uiEscape(uiVersion)}</p><p class="hint" id="update-status" role="status">${uiEscape(status)}</p>${uiButton(uiUpdate.busy?'Проверяем…':'Обновить','update-app','primary wide')}<p class="hint">Обновление не удаляет портфели, операции и настройки. Отложенная новая версия включится после полного закрытия приложения.</p></div>`;}
function uiSettings(){return `<div class="panel"><span class="pill">Все данные в Firefox</span><p class="hint">Хранение в этом браузере. Без синхронизации, уведомлений и загрузки котировок.</p></div>${uiUpdatePanel()}${uiSectionTitle('Оформление')}<div class="panel theme-panel">${uiSelect('theme-preference','Тема «Сапфир»',[['system','Как на устройстве'],['light','Светлая'],['dark','Тёмная']],uiAppearance.getState().preference)}<p class="hint" id="theme-status" role="status">${uiEscape(uiThemeStatus())}</p></div>${uiSectionTitle('Новые портфели')}<div class="panel">${uiSelect('default-currency','Валюта по умолчанию',uiCurrencyOptions(uiDefaultCurrency),uiDefaultCurrency)}</div>${uiSectionTitle('Резервные копии')}<div class="panel">${uiButton('Экспортировать JSON','export','primary wide')}<div class="toolbar">${uiButton('Импорт JSON / CSV','import','secondary wide')}${uiButton('Предыдущее автосохранение','export-backup','textbutton')}${uiButton('Копия до обновления приложения','export-before-update','textbutton')}${uiButton('Копия до обновления формата','export-before-upgrade','textbutton')}${uiButton('Копия до импорта','export-before-import','textbutton')}</div></div>${uiSectionTitle('Офлайн и Firefox')}<div class="panel"><p class="hint" style="margin-top:0">Открывайте постоянную ссылку в обычной вкладке Firefox. После первого открытия приложение сохраняет офлайн-копию. Самостоятельный Kapital.html включён в ZIP.</p><p class="hint">Для переноса между браузерами используйте JSON. Не очищайте данные сайта без резервной копии.</p>${uiButton('Запросить постоянное хранение','persist','textbutton')}<p class="hint">${uiEscape(uiOffline)}</p></div>${uiSectionTitle('Как считается результат')}<div class="panel"><p class="hint" style="margin-top:0">Средневзвешенная себестоимость пересчитывается по хронологии. Покупка списывает стоимость и комиссию; продажа зачисляет стоимость за вычетом комиссии. Комиссии учитываются в доходе один раз. Ручной результат продажи не меняет фактическую выручку.</p><p class="hint">Снимки дают результат с даты начальных остатков, а не историческую прибыль. Валюты не объединяются. Купонная доходность не равна доходности к погашению.</p></div>`;}
function uiContent(){if(uiScreen==='home')return uiHome();if(uiScreen==='settings')return uiSettings();if(uiScreen==='import')return uiImportScreen();if(uiScreen==='new'||uiScreen==='rename'){const p=uiCurrent();return `${uiButton('‹ Портфели','home','back')}<h2>${uiScreen==='new'?'Новый портфель':'Переименовать портфель'}</h2><form class="form" data-ledger-form="portfolio">${uiField('portfolio-name','Название',uiScreen==='new'?'':p?.name||'',{required:true,maxlength:60})}${uiScreen==='new'?uiSelect('portfolio-currency','Начальная валюта',uiCurrencyOptions(),uiDefaultCurrency)+uiField('portfolio-initial','Начальный денежный остаток','0',{decimal:true,required:true}):''}<div class="form-actions"><button class="primary" type="submit">Сохранить</button>${uiButton('Отмена','home')}</div></form>`;}if(!uiCurrent())return uiEmpty('Сначала создайте портфель.');if(uiScreen==='portfolio')return uiOverview();if(uiScreen==='assets')return uiAssets();if(uiScreen==='asset')return uiAssetPage();if(uiScreen==='asset-edit')return uiAssetForm();if(uiScreen==='issuers')return uiIssuers();if(uiScreen==='issuer-edit')return uiIssuerForm();if(uiScreen==='entry')return uiEntryForm();if(uiScreen==='cash')return uiCash();if(uiScreen==='graph')return uiGraph();if(uiScreen==='composition'){const v=uiView();return `${uiPortfolioPicker()}${uiCurrencyPicker(v)}${uiChartComposition(v)}`;}if(uiScreen==='history')return `${uiPortfolioPicker()}${uiSectionTitle('История учёта',uiButton('+ Операция','entry','textbutton','data-kind="deposit"'))}${uiJournal()}`;if(uiScreen==='profit'){const e=uiData.entries.find(e=>e.id===uiEditing),result=uiView().entryResults.get(e?.id);return `${uiButton('‹ Операции','history','back')}<h2>Прибыль / убыток продажи</h2><div class="panel"><p class="hint">Автоматически: ${result?.autoProfitMinor===null?'не определён':uiMoney(result?.autoProfitMinor||0,e.currency)}</p><p class="hint">Ручное значение полностью заменяет автоматическое в сводках и графике. Денежная выручка не меняется.</p></div><form class="form" data-ledger-form="profit">${uiField('profit-override','Ручной результат, '+e.currency,e.profitOverrideMinor===undefined?'':e.profitOverrideMinor/100,{decimal:true})}<div class="form-actions"><button type="submit" class="primary">Сохранить</button>${uiButton('Сбросить к автоматическому','profit-reset')}</div></form>`;}if(uiScreen==='cash-opening'){const p=uiCurrent();return `${uiButton('‹ Наличные','cash','back')}<h2>Начальные денежные остатки</h2><p class="hint">Это база до начала журнала, а не новое пополнение. Для поступления денег используйте операцию «Пополнение».</p><form class="form" data-ledger-form="cash-opening">${uiSelect('opening-cash-currency','Валюта',uiCurrencyOptions(uiCurrency),uiCurrency)}${uiField('opening-cash-amount','Начальный остаток',(p.openingCash[uiCurrency]||0)/100,{decimal:true,required:true})}${uiField('opening-capital','Начальный вложенный капитал',(p.baselineCapital[uiCurrency]||0)/100,{decimal:true,required:true})}<div class="form-actions"><button type="submit" class="primary">Сохранить базу</button>${uiButton('Отмена','cash')}</div></form>`;}if(uiScreen==='opening'){const a=uiCurrentAsset(),o=a?.opening.find(o=>o.currency===uiCurrency);return `${uiButton('‹ Инструмент','asset','back')}<h2>Начальные остатки</h2><p class="hint">Это снимок, а не покупка. Изменение пересчитает базу результата. Для полной истории загрузите операции в новый портфель.</p><form class="form" data-ledger-form="opening">${uiSelect('opening-currency','Валюта',uiCurrencyOptions(uiCurrency),uiCurrency)}${uiField('opening-quantity','Количество',o?o.quantityUnits/1000000:'0',{decimal:true,required:true})}${uiField('opening-value','Начальная оценка всей позиции',o?o.valueMinor/100:'0',{decimal:true,required:true})}${uiField('opening-date','Дата снимка',o?.date||uiCurrent().snapshotDate||ledgerToday(),{type:'date',required:true})}<div class="form-actions"><button type="submit" class="primary">Сохранить остатки</button>${uiButton('Отмена','asset')}</div></form>`;}return '';}

async function uiLoad(){const saved=await uiStore.read();if(uiImport.preview&&saved?.revision!==uiRevision)uiImport.preview=null;uiData=saved?.data||emptyLedger();uiRevision=saved?.revision||0;uiSaved=saved?.updatedAt||'';uiEnsure();}
async function uiSave(next,options={}){if(!uiReady)throw new Error('Локальное сохранение недоступно.');validateLedger(next);const saved=await uiStore.save(next,uiRevision,options);uiData=saved.data;uiRevision=saved.revision;uiSaved=saved.updatedAt;uiImport.preview=null;uiChannel?.postMessage({revision:uiRevision});}
function uiFail(error){uiMessage=error?.message||String(error);uiError=true;uiRender();}
function uiFormError(form,error){form.querySelector('[role=alert]')?.remove();const box=document.createElement('div');box.className='notice error';box.role='alert';box.textContent=error?.message||String(error);form.prepend(box);if(error?.code==='CONFLICT'){const b=document.createElement('button');b.type='button';b.className='secondary';b.dataset.action='reload';b.textContent='Обновить данные';box.append(b);}box.scrollIntoView({block:'center'});}
async function uiDialog(title,text,choices=[['yes','Продолжить','primary'],['cancel','Отмена','secondary']],fields=''){return new Promise(resolve=>{const dialog=document.createElement('dialog');dialog.innerHTML=`<form><h2>${uiEscape(title)}</h2><p>${uiEscape(text)}</p><div class="form">${fields}</div><div class="toolbar">${choices.map(([value,label,style])=>`<button type="submit" class="${style}" value="${value}">${label}</button>`).join('')}</div></form>`;const form=dialog.querySelector('form');form.addEventListener('submit',e=>{e.preventDefault();dialog.close(e.submitter?.value||'cancel');});dialog.addEventListener('cancel',()=>dialog.returnValue='cancel');dialog.addEventListener('close',()=>{const values=Object.fromEntries(new FormData(form));const answer={choice:dialog.returnValue||'cancel',values};dialog.remove();resolve(answer);},{once:true});document.body.append(dialog);dialog.showModal();});}
const uiConfirm=async(title,text,accept='Продолжить')=>(await uiDialog(title,text,[['yes',accept,'primary'],['cancel','Отмена','secondary']])).choice==='yes';
async function uiExport(body,name,type='application/json'){const file=new File([body],name,{type});if(navigator.canShare?.({files:[file]})&&navigator.share){try{await navigator.share({files:[file],title:'Капитал · Фокус'});return;}catch(error){if(error.name==='AbortError')return;}}const url=URL.createObjectURL(file),link=document.createElement('a');link.href=url;link.download=name;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function uiBondValues(form,currency){const fields=new FormData(form);return{currency,nominalMinor:parseMinor(fields.get('nominal')||'0'),couponMinor:parseMinor(fields.get('coupon-amount')||'0'),couponRate:Number(String(fields.get('coupon-rate')||'0').replace(',','.')),periodMonths:Number(fields.get('coupon-frequency')),anchorDate:String(fields.get('coupon-date')||''),maturityDate:String(fields.get('maturity-date')||'')};}
function uiBuildEntry(form){const f=new FormData(form),kind=form.dataset.kind,old=uiData.entries.find(e=>e.id===uiEditing),entry={...(old||{}),id:old?.id||ledgerId(),portfolioId:String(f.get('entry-portfolio')),kind,date:String(f.get('entry-date')),note:String(f.get('entry-note')||'')};
  if(kind==='fx'){entry.fromCurrency=String(f.get('from-currency'));entry.toCurrency=String(f.get('to-currency'));entry.fromMinor=parseMinor(f.get('from-amount'));entry.toMinor=parseMinor(f.get('to-amount'));return entry;}
  entry.currency=String(f.get('entry-currency'));if(f.has('entry-asset'))entry.assetId=String(f.get('entry-asset'));
  if(['buy','sell','redemption'].includes(kind)){entry.quantityUnits=parseUnits(f.get('entry-quantity'));entry.priceMinor=parseMinor(f.get('entry-price'));entry.feeMinor=parseMinor(f.get('entry-fee')||'0');entry.feeCurrency=String(f.get('fee-currency')||entry.currency);if(['buy','sell'].includes(kind)&&!entry.priceMinor)throw new Error('Цена сделки должна быть больше нуля.');if(!old||old.quantityUnits!==entry.quantityUnits||old.priceMinor!==entry.priceMinor)delete entry.grossMinor;}
  else{entry.amountMinor=parseMinor(f.get('entry-amount'));if(['dividend','coupon'].includes(kind)){entry.taxMinor=parseMinor(f.get('tax-amount')||'0');entry.taxRate=Number(String(f.get('tax-rate')||'0').replace(',','.'));if(kind==='coupon'&&f.get('scheduled-date'))entry.scheduledDate=String(f.get('scheduled-date'));}}
  return entry;
}
function uiEntryUpdate(){const form=uiApp.querySelector('[data-ledger-form=entry]');if(!form)return;const target=form.querySelector('#entry-preview');try{const e=uiBuildEntry(form),p=uiData.portfolios.find(p=>p.id===e.portfolioId),view=ledgerView(uiData,p.id),cash=view.currencies.get(e.currency)?.cash||0;
    if(e.kind==='fx'){if(e.fromCurrency===e.toCurrency)throw new Error('Выберите разные валюты.');target.textContent=`Обмен: ${uiMoney(e.fromMinor,e.fromCurrency)} → ${uiMoney(e.toMinor,e.toCurrency)} · Курс ${(e.toMinor/e.fromMinor).toLocaleString('ru-RU',{maximumFractionDigits:8})}`;return;}
    if(['buy','sell','redemption'].includes(e.kind)){const gross=entryGross(e),fee=e.feeCurrency===e.currency?e.feeMinor:0;let text=`${e.kind==='buy'?'Спишется':'Зачислится'}: ${uiMoney(e.kind==='buy'?gross+fee:gross-fee,e.currency)}`;if(e.feeMinor&&e.feeCurrency!==e.currency)text+=` · Комиссия отдельно ${uiMoney(e.feeMinor,e.feeCurrency)}`;if(e.kind==='buy')text+=` · Доступно ${uiMoney(cash,e.currency)}`;else{const candidate=structuredClone(uiData);candidate.entries=candidate.entries.filter(x=>x.id!==e.id);candidate.entries.push(e);const r=ledgerView(candidate,p.id,'9999-12-31').entryResults.get(e.id);text+=` · Результат ${r?.profitMinor===null?'не определён: проверьте остаток':uiMoney(r?.profitMinor||0,e.currency)}`;}target.textContent=text;}
    else if(['dividend','coupon'].includes(e.kind))target.textContent='После налога зачислится: '+uiMoney(e.amountMinor-(e.taxMinor||0),e.currency);
    else target.textContent=(e.kind==='deposit'?'Зачислится: ':'Спишется: ')+uiMoney(e.amountMinor,e.currency)+' · Сейчас '+uiMoney(cash,e.currency);
  }catch(error){target.textContent=error.message||'Введите параметры операции.';}}
