  if(kind==='import-preview'){const serial=uiImport.serial;let text=uiImport.text;if(uiImport.method==='file'){if(!uiImport.file)throw new Error('Сначала выберите файл.');if(uiImport.file.size>LEDGER_MAX_BYTES)throw new Error('Файл больше 12 МБ.');text=await uiImport.file.text();}const parsed=parseLedgerFile(text,{format:uiImport.format,defaultKind:uiImport.defaultKind});const preview=prepareLedgerImport(uiData,parsed,{target:uiImport.target,name:uiImport.name,replaceAll:uiImport.mode==='restore'});if(serial!==uiImport.serial)throw new Error('Источник изменился, проверьте его заново.');preview.baseRevision=uiRevision;uiImport.preview=preview;uiBusy=false;uiRender();uiApp.querySelector('.import-review')?.scrollIntoView({block:'start'});return;}
